"""
Region 5 major power outage forecast dashboard (Shiny for Python, runs in Shinylive).

Run locally:      shiny run dashboard/app.py
Export for web:   shinylive export dashboard site
Data comes from dashboard/data/, made by build_dashboard_data.py.
"""

from pathlib import Path

import pandas as pd
from shiny import App, reactive, render, ui

import helpers as h

D = h.load_all()
WEEKS = h.week_choices(D["pred"])
COUNTIES = dict(sorted(zip(D["counties"]["fips"], D["counties"]["label"]), key=lambda kv: kv[1]))
MODEL_CHOICES = {"p_model7": "Model 7 (logistic)", "p_gbm": "Gradient boosting",
                 "p_base": "Baseline (county history)"}
HL = h.headline(D)

# start on the week with the most major-outage counties, so the map has something to show
_busiest = D["pred"].groupby("week_start")["major"].sum().idxmax()
START_WEEK = pd.Timestamp(_busiest).strftime("%Y-%m-%d")


def pct(x, d=1):
    return "–" if pd.isna(x) else f"{x * 100:.{d}f}%"


def boot_text(r):
    if r is None:
        return "Run evaluate_stage2.py"
    return f"{r['difference']:+.3f} (95% interval {r['ci_low']:+.3f} to {r['ci_high']:+.3f})"


overview = ui.nav_panel(
    "Overview",
    ui.layout_columns(
        ui.value_box("Model 7 PR-AUC", f"{HL['p_model7']:.3f}",
                     f"Baseline {HL['p_base']:.3f} · no skill {HL['no_skill']:.3f}"),
        ui.value_box("Gradient boosting PR-AUC", f"{HL['p_gbm']:.3f}",
                     "vs. Model 7: " + boot_text(HL.get("boot_gbm_m7"))),
        ui.value_box("Major-outage county-weeks", f"{HL['major_observed']:,}",
                     f"Model 7 expected {HL['major_predicted_m7']:,.0f}"),
        ui.value_box("Test period", f"{HL['weeks']} Mondays",
                     f"2024–2025 · {HL['counties']} counties"),
        col_widths=[3, 3, 3, 3],
    ),
    ui.card(
        ui.card_header("What this dashboard shows"),
        ui.markdown(
            "Every Monday morning, each model gives each county a chance that **at least 5% of its "
            "homes will be without power at the same time** some time that week (a *major outage*). "
            "The models were trained on 2015–2023 EAGLE-I data and are shown here on **2024–2025**, "
            "weeks they never saw.\n\n"
            "- **Baseline**: how often the county had a major outage in that calendar month, 2015–2023.\n"
            "- **Model 7**: logistic regression with county traits, recent outages and the "
            "weather forecast issued by Monday 12 UTC.\n"
            "- **Gradient boosting**: the same inputs in a tree model (Stage 2).\n\n"
            "**PR-AUC** (precision–recall area) is the main score: higher is better and "
            f"{HL['no_skill']:.3f} means no skill. "
            "Model 7 minus baseline: " + boot_text(HL.get("boot_m7_base")) + "."
        ),
    ),
)

risk_map = ui.nav_panel(
    "Weekly risk map",
    ui.layout_sidebar(
        ui.sidebar(
            ui.input_select("week", "Monday forecast for", WEEKS, selected=START_WEEK),
            ui.input_radio_buttons("map_model", "Model", MODEL_CHOICES),
            ui.output_ui("week_numbers"),
            width=300,
        ),
        ui.card(ui.card_header("Predicted chance vs. what happened"),
                ui.output_plot("map_plot", height="540px"), full_screen=True),
        ui.card(ui.card_header("Ten highest-risk counties that week"), ui.output_data_frame("top_table")),
    ),
)

explorer = ui.nav_panel(
    "County explorer",
    ui.layout_sidebar(
        ui.sidebar(
            ui.input_selectize("county", "County", COUNTIES,
                               selected="26163" if "26163" in COUNTIES else next(iter(COUNTIES))),
            ui.output_ui("county_box"),
            width=300,
        ),
        ui.card(ui.output_plot("county_plot", height="560px"), full_screen=True),
    ),
)

models = ui.nav_panel(
    "Model comparison",
    ui.layout_columns(
        ui.card(ui.card_header("Precision–recall curves, 2024–2025"), ui.output_plot("pr_plot", height="440px")),
        ui.card(ui.card_header("Is the gain real? Week-block bootstrap, 2,000 resamples"),
                ui.output_plot("boot_plot", height="440px"),
                ui.p("If an interval crosses 0, the difference could be chance.", class_="note")),
        col_widths=[6, 6],
    ),
    ui.card(ui.card_header("PR-AUC, Models 1–8"),
            ui.output_plot("scores_plot", height="420px"),
            ui.p("Model 8 (hatched) uses the week's own storm reports, so it is a benchmark, not a forecast.",
                 class_="note")),
)

where = ui.nav_panel(
    "Where it works",
    ui.layout_sidebar(
        ui.sidebar(
            ui.input_radio_buttons("grouping", "Split the test weeks by",
                                   sorted(D["sub"]["grouping"].unique()) if not D["sub"].empty else []),
            ui.p("Each bar compares a model with the baseline in the same group. Groups differ in "
                 "their share of major-outage weeks, so raw PR-AUC is not compared across groups.", class_="note"),
            width=300,
        ),
        ui.layout_columns(
            ui.card(ui.card_header("Gain over the county-history baseline"), ui.output_plot("sub_plot", height="380px")),
            ui.card(ui.card_header("Calibration: do the chances mean what they say?"),
                    ui.output_plot("cal_plot", height="380px")),
            col_widths=[7, 5],
        ),
        ui.card(ui.output_data_frame("sub_table")),
    ),
)

peaks = ui.nav_panel(
    "Peak storms",
    ui.card(ui.card_header("Each state's largest outage, 2015–2025 (Table 3)"), ui.output_data_frame("peak_table")),
    ui.card(
        ui.card_header("Monday forecasts around a peak in the test years"),
        ui.input_select("peak", "Peak", {r["fips"]: f"{r['county']}, {r['state']} ({r['date']})"
                                          for _, r in D["peaks"].iterrows()
                                          if pd.Timestamp(r["date"]).year >= 2024}),
        ui.output_plot("peak_plot", height="320px"),
    ),
)

app_ui = ui.page_navbar(
    overview, risk_map, explorer, models, where, peaks,
    title="Region 5 Outage Forecasts",
    header=ui.include_css(Path(__file__).parent / "styles.css"),
    footer=ui.div("Conor Stewart · ALY4850 Capstone · EAGLE-I outage data, 2015–2025", class_="footer"),
    fillable=False,
)


def server(input, output, session):

    @render.ui
    def week_numbers():
        s = h.week_summary(D, input.week(), input.map_model())
        return ui.markdown(
            f"**{s['major']}** of {s['counties']} counties had a major outage.\n\n"
            f"The model expected **{s['expected']:.1f}**.\n\n"
            f"**{s['top_hit']}** of its ten highest-risk counties had one.")

    @render.plot
    def map_plot():
        return h.risk_map(D, input.week(), input.map_model())

    @render.data_frame
    def top_table():
        return render.DataGrid(h.top_counties(D, input.week(), input.map_model()), width="100%")

    @render.ui
    def county_box():
        f = h.county_facts(D, input.county())
        if not f:
            return ui.p("No data for this county.")
        kind = "Nonmetro" if f["nonmetro"] == 1 else "Metro"
        return ui.markdown(
            f"**{f['label']}**\n\n"
            f"- {f['housing_units']:,.0f} homes · {f['density']:,.0f} per sq. mi. · {kind}\n"
            f"- Vacation homes: {pct(f['seasonal'])}\n"
            f"- Major-outage weeks 2015–2025: {pct(f['major_share'])}\n"
            f"- 2024–2025: **{f['test_major']}** major-outage weeks of {f['test_weeks']}; "
            f"Model 7 expected {f['test_expected']:.1f}")

    @render.plot
    def county_plot():
        return h.county_history(D, input.county())

    @render.plot
    def pr_plot():
        return h.pr_curves(D)

    @render.plot
    def boot_plot():
        return h.bootstrap_chart(D)

    @render.plot
    def scores_plot():
        return h.scores_chart(D)

    @render.plot
    def sub_plot():
        return h.subgroup_chart(D, input.grouping())

    @render.plot
    def cal_plot():
        return h.calibration_chart(D)

    @render.data_frame
    def sub_table():
        return render.DataGrid(h.subgroup_table(D, input.grouping()), width="100%")

    @render.data_frame
    def peak_table():
        return render.DataGrid(h.peaks_table(D), width="100%")

    @render.plot
    def peak_plot():
        row = D["peaks"][D["peaks"]["fips"] == input.peak()]
        if row.empty:
            return None
        return h.peak_week_chart(D, input.peak(), row.iloc[0]["date"])


app = App(app_ui, server)

/* Minimal, professional look for the Region 5 outage dashboard.
   Neutral page, white cards with hairline borders, no shadows, one accent (blue). */

:root {
  --page: #f6f6f4;
  --card: #ffffff;
  --ink: #1a1a19;
  --ink-2: #52514e;
  --muted: #898781;
  --line: #e4e3dd;
  --accent: #2a78d6;
  --bs-body-font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --bs-body-color: var(--ink);
  --bs-border-color: var(--line);
}

body { background: var(--page); font-size: 14px; letter-spacing: 0.005em; }

/* Navbar: white bar, thin rule, quiet tabs with an underline for the active page */
.navbar { background: var(--card) !important; border-bottom: 1px solid var(--line); box-shadow: none; padding: 0 1.25rem; }
.navbar-brand { font-weight: 600; font-size: 15px; color: var(--ink) !important; letter-spacing: -0.01em; }
.navbar .nav-link { color: var(--ink-2) !important; font-size: 13.5px; padding: 1rem 0.85rem !important;
                    border-bottom: 2px solid transparent; }
.navbar .nav-link:hover { color: var(--ink) !important; }
.navbar .nav-link.active { color: var(--ink) !important; border-bottom-color: var(--accent); font-weight: 500; }

/* Content width and spacing */
.tab-content { max-width: 1360px; margin: 0 auto; padding: 1.5rem 1.25rem 0.5rem; }

/* Cards: flat, hairline border */
.card, .bslib-card { background: var(--card); border: 1px solid var(--line) !important; border-radius: 10px;
                     box-shadow: none !important; margin-bottom: 1.25rem; }
.card-header { background: transparent; border-bottom: none; padding: 1rem 1.25rem 0.25rem;
               font-size: 13px; font-weight: 600; color: var(--ink); }
.card-body { padding: 0.75rem 1.25rem 1.1rem; }

/* Value boxes: plain white tiles, small label, large number */
.bslib-value-box { background: var(--card) !important; color: var(--ink) !important; }
.bslib-value-box .value-box-title { font-size: 12px; font-weight: 500; color: var(--muted);
                                    text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 0.35rem; }
.bslib-value-box .value-box-value { font-size: 30px; font-weight: 600; letter-spacing: -0.02em; line-height: 1.1; }
.bslib-value-box p { font-size: 12.5px; color: var(--ink-2); margin: 0.35rem 0 0; }

/* Sidebar: same white as cards, thin divider */
.bslib-sidebar-layout { border: 1px solid var(--line) !important; border-radius: 10px; background: var(--card);
                        margin-bottom: 1.25rem; }
.bslib-sidebar-layout > .sidebar { background: var(--card) !important; border-right: 1px solid var(--line) !important; }
.bslib-sidebar-layout > .main { background: var(--page); padding: 1.25rem; }
.sidebar .form-label, .sidebar label.control-label { font-size: 12px; font-weight: 600; color: var(--ink-2);
                                                    text-transform: uppercase; letter-spacing: 0.05em; }
.sidebar p, .sidebar li { font-size: 13px; color: var(--ink-2); }

/* Inputs */
.form-select, .selectize-input, .form-control { border: 1px solid var(--line) !important; border-radius: 6px;
                                                box-shadow: none !important; font-size: 13.5px; }
.form-check-input:checked { background-color: var(--accent); border-color: var(--accent); }

/* Tables: no stripes, light rules */
.shiny-data-grid table { font-size: 13px; }
.shiny-data-grid thead th { background: var(--card) !important; color: var(--muted); font-weight: 600;
                            font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.05em;
                            border-bottom: 1px solid var(--line) !important; }
.shiny-data-grid tbody td { border-bottom: 1px solid #f0efeb !important; }

/* Text */
.card-body p, .card-body li { color: var(--ink-2); line-height: 1.55; }
.card-body strong { color: var(--ink); font-weight: 600; }
.note { font-size: 12.5px; color: var(--muted); margin-top: 0.25rem; }
.footer { color: var(--muted); font-size: 12px; text-align: center; padding: 1rem 0 1.5rem; }
